argv:
const assert = require('node:assert/strict');
const {htmlEscapeTag, htmlUnescapeTag} = require('./index.js');
for (const value of [undefined, true, 42, null]) {
 assert.equal(htmlEscapeTag`prefix:${value}:suffix`, `prefix:${String(value)}:suffix`);
 assert.equal(htmlUnescapeTag`prefix:${value}:suffix`, `prefix:${String(value)}:suffix`);
}
assert.equal(htmlEscapeTag`<b>${{toString: () => '<&>'}}</b>`, '<b>&lt;&amp;&gt;</b>');
assert.equal(htmlUnescapeTag`<b>${{toString: () => '&lt;&amp;&gt;'}}</b>`, '<b><&></b>');
console.log('tag substitutions converted; literal template segments preserved');

const assert = require('node:assert/strict');
const {htmlEscape, htmlUnescape} = require('./index.js');
for (const input of ['', 'plain text', '<&>\"\'', '🦄 & 🐐']) {
 assert.equal(htmlUnescape(htmlEscape(input)), input);
}
assert.equal(htmlUnescape('&amp;lt;'), '&lt;');
console.log('ordinary string round trips and single-pass unescape preserved');

const assert = require('node:assert/strict');
const {htmlEscape, htmlUnescape} = require('./index.js');
for (const value of [undefined, true, 42, null]) {
 assert.throws(() => htmlEscape(value), TypeError);
 assert.throws(() => htmlUnescape(value), TypeError);
}
console.log('regular functions retain existing non-string rejection');

